(() => {
 'use strict';
 const app=document.querySelector('#app'),toastEl=document.querySelector('#toast');
 const KEY='paizhao-full-concept-v2';
 const empty=()=>({registered:false,pet:null,pets:[],currentPetId:null,posts:[],likes:[],saved:[],follows:[],comments:{},walks:[],health:[],adoptRequests:[],chat:[]});
 let data;try{data={...empty(),...JSON.parse(localStorage.getItem(KEY)||'{}')}}catch{data=empty()}
 if(data.pet&&!data.pets.length){data.pet.id=data.pet.id||'legacy';data.pets=[data.pet];data.currentPetId=data.pet.id}
 let view='home',tab='home',from='home',detailId='',selectedPet='狗',sterilized='未填写',filter='推荐',imageData='',topic='',voice='owner',adoptionId='',walk=null,watchId=null,routeId='',artType='狗',chatDraft='',petDraft={},petFormNew=false,calendarOffset=0,calendarFilter='',stack=[],shopFilter='全部',shopItemId='s1',renderedView='',ignoreNextPop=false;
 const $=s=>document.querySelector(s), e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const asset={狗:'assets/dog.webp',猫:'assets/cat.webp',兔:'assets/rabbit.webp',水族:'assets/aquarium.webp',其他:'assets/placeholder.svg',鸟:'assets/placeholder.svg',爬宠:'assets/placeholder.svg',小宠:'assets/placeholder.svg'};
 const demoPet={id:'demo',name:'奶豆',kind:'狗',age:'2岁',sterilized:'未填写',demo:true};
 const pet=()=>data.pets.find(x=>x.id===data.currentPetId)||data.pet||demoPet, petPhoto=(p=pet())=>p.photo||asset[p.kind]||asset['其他'];
 const petSelector=()=>`<div class="chip-row" style="margin:10px 0 14px">${(data.pets.length?data.pets:[demoPet]).map(p=>`<button class="chip ${pet().id===p.id?'on':''}" data-a="choose-active-pet" data-id="${e(p.id)}">${e(p.name)}${p.demo?'（示例）':''}</button>`).join('')}<button class="chip" data-a="add-pet">＋ 添加伙伴</button></div>`;
 const petIdCard=()=>`<div class="pet-id-card"><span>PAW ID · 本机示意编号</span><strong>${pet().demo?'DEMO-001':'PZ-'+e(pet().id.slice(-6))}</strong></div>`;
 const examples=[{id:'e1',animal:'狗',author:'山山和阿禾',pet:'山山',title:'今天的快乐，是草地味的',text:'和山山在公园慢慢散步，遇到了新朋友。你家小伙伴今天在哪里玩？',image:asset['狗'],likes:128},{id:'e2',animal:'猫',author:'栗子的家',pet:'栗子',title:'晒晒我家的午睡选手',text:'阳光照进来，栗子找到了最舒服的位置。',image:asset['猫'],likes:86},{id:'e3',animal:'兔',author:'团团与我',pet:'团团',title:'小兔子今天也很有精神',text:'团团吃完饭就在阳光里发呆。',image:asset['兔'],likes:53},{id:'e4',animal:'水族',author:'水草间',pet:'小鱼',title:'一方水里的小小世界',text:'换水后的水草更透亮了。',image:asset['水族'],likes:42}];
 const adopt=[{id:'a1',name:'小满',kind:'狗',age:'约1岁',place:'示例城市 · 城区',image:asset['狗'],text:'活泼亲人，喜欢散步。请先了解领养要求，再与救助方沟通。'},{id:'a2',name:'栗子',kind:'猫',age:'约8个月',place:'示例城市 · 城区',image:asset['猫'],text:'性格温柔，喜欢靠近人。希望找到可以耐心陪伴它的家庭。'},{id:'a3',name:'团团',kind:'兔',age:'约1岁',place:'示例城市 · 城区',image:asset['兔'],text:'喜欢安静环境，希望得到适合兔子的日常照护。'}];
 const icons={map:'<path d="m3 6 5-2 8 2 5-2v14l-5 2-8-2-5 2z"/><path d="M8 4v14M16 6v14"/>',community:'<path d="M20 11a8 8 0 0 1-8 8 9 9 0 0 1-3.7-.8L4 20l1.3-4A8 8 0 1 1 20 11Z"/><path d="M8 11h.01M12 11h.01M16 11h.01"/>',plus:'<path d="M12 4v16M4 12h16"/>',care:'<rect x="4" y="5" width="16" height="15" rx="3"/><path d="M8 3v4M16 3v4M4 10h16M10 15h4M12 13v4"/>',user:'<circle cx="12" cy="8" r="3.4"/><path d="M5.5 20c0-3.3 2.8-5.4 6.5-5.4s6.5 2.1 6.5 5.4"/>',paw:'<ellipse cx="12" cy="16" rx="4.5" ry="3.5"/><circle cx="5.5" cy="10.5" r="1.5"/><circle cx="9.5" cy="6.5" r="1.5"/><circle cx="14.5" cy="6.5" r="1.5"/><circle cx="18.5" cy="10.5" r="1.5"/>',bell:'<path d="M18 9a6 6 0 0 0-12 0c0 6-2 6-2 7.5h16C20 15 18 15 18 9ZM10 20h4"/>',back:'<path d="m14.5 5-7 7 7 7"/>',pin:'<path d="M19 10c0 5-7 11-7 11s-7-6-7-11a7 7 0 1 1 14 0Z"/><circle cx="12" cy="10" r="2.3"/>',expand:'<path d="M4 9V4h5M15 4h5v5M20 15v5h-5M9 20H4v-5"/>',route:'<circle cx="6" cy="18" r="2"/><circle cx="18" cy="6" r="2"/><path d="M8 18h4a3 3 0 0 0 0-6h-1a3 3 0 0 1 0-6h5"/>',album:'<rect x="3" y="5" width="18" height="15" rx="3"/><circle cx="8.5" cy="10" r="1.5"/><path d="m4 18 5-5 3 3 3-4 5 6"/>',house:'<path d="m3 11 9-7 9 7M5 10v10h14V10M10 20v-6h4v6"/>',heart:'<path d="M20.5 8.8c0 4-4.7 7.7-8.5 10.4-3.8-2.7-8.5-6.4-8.5-10.4a4.4 4.4 0 0 1 8.5-1.5 4.4 4.4 0 0 1 8.5 1.5Z"/>',medical:'<path d="M9 3h6v4h4v6h-4v4H9v-4H5V7h4z"/><path d="M4 20h16"/>',spark:'<path d="m12 2 1.7 5.5L19 9l-5.3 1.7L12 16l-1.7-5.3L5 9l5.3-1.5zM19 15l.8 2.2L22 18l-2.2.8L19 21l-.8-2.2L16 18l2.2-.8z"/>',camera:'<path d="M4 8h3l2-3h6l2 3h3v11H4z"/><circle cx="12" cy="13.5" r="3"/>',breed:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m15.5 15.5 4.5 4.5M8 10h.01M13 10h.01M9 13c1 .8 2 .8 3 0"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',water:'<path d="M12 3s-6 6-6 10a6 6 0 0 0 12 0c0-4-6-10-6-10Z"/><path d="M9 14c.2 1.5 1.3 2.5 3 2.5"/>',mark:'<path d="M5 18c2-7 5-10 11-12 0 5-3 10-11 12Z"/><path d="m5 18 14-2"/>',friends:'<circle cx="9" cy="8" r="3"/><path d="M3.5 19c0-3 2.2-5 5.5-5s5.5 2 5.5 5M16 5.5a3 3 0 0 1 0 5.8M17 14c2.1.6 3.4 2.2 3.4 4.5"/>',history:'<path d="M4.5 8V4.5M4.5 8H8M5 8a8 8 0 1 1-.5 7"/><path d="M12 7v5l3 2"/>',edit:'<path d="m4 16-.5 4.5L8 20 19.5 8.5 15.5 4.5Z"/><path d="m14.5 5.5 4 4"/>',shield:'<path d="M12 2.5 20 6v5.6c0 4.2-2.8 7.1-8 9.9-5.2-2.8-8-5.7-8-9.9V6Z"/><path d="m8.5 12 2.2 2.2 4.8-5"/>',bag:'<path d="M5 8h14l1 12H4zM9 9V7a3 3 0 0 1 6 0v2"/>',search:'<circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 4.3 4.3"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4Z"/>',vaccine:'<path d="m7 17 9-9M15 4l5 5M4 20l3-3M10 6l8 8M5 14l5 5"/>',bath:'<path d="M4 13h16v2a5 5 0 0 1-5 5H9a5 5 0 0 1-5-5zM6 13V7a2 2 0 0 1 4 0"/><circle cx="15" cy="6" r="1"/>',pill:'<path d="M7 18a4 4 0 0 1-1-6l6-6a4 4 0 0 1 6 6l-6 6a4 4 0 0 1-5 0ZM9 9l6 6"/>',scale:'<rect x="4" y="4" width="16" height="16" rx="4"/><path d="M8 10a4 4 0 0 1 8 0M12 8l1 2"/>',check:'<path d="m5 12 4 4L19 6"/>',trash:'<path d="M4 7h16M9 7V4h6v3M6 7l1 13h10l1-13M10 10v7M14 10v7"/>',logout:'<path d="M10 4H5v16h5M13 8l4 4-4 4M8 12h9"/>'};
 const ico=n=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[n]||icons.paw}</svg>`;
 let t;function toast(s){toastEl.textContent=s;toastEl.classList.add('show');clearTimeout(t);t=setTimeout(()=>toastEl.classList.remove('show'),2600)}
 function save(){try{localStorage.setItem(KEY,JSON.stringify(data));return true}catch{toast('本机空间不足，请减少图片或清除体验数据');return false}}
 const today=()=>{let d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
 const status=()=>'<div class="status"><span>9:41</span><span>● ▪ ▰</span></div>';
 const nav=()=>`<nav class="nav" aria-label="主要导航"><button class="${tab==='home'?'active':''}" data-a="tab" data-v="home">${ico('map')}<span>地图</span></button><button class="${tab==='community'?'active':''}" data-a="tab" data-v="community">${ico('community')}<span>社区</span></button><button class="plus" data-a="compose" aria-label="发布动态">${ico('plus')}</button><button class="${tab==='care'?'active':''}" data-a="tab" data-v="care">${ico('care')}<span>养护</span></button><button class="${tab==='profile'?'active':''}" data-a="tab" data-v="profile">${ico('user')}<span>我的</span></button></nav>`;
 const shell=(html,showNav=true)=>`<div class="screen">${status()}${html}</div>${showNav?nav():''}`;
 const head=(title,right='',action='')=>`<div class="small-head"><button class="back" data-a="back" aria-label="返回">${ico('back')}</button><h1>${e(title)}</h1>${right?`<button class="right" data-a="${e(action)}">${e(right)}</button>`:''}</div>`;
 const sec=(title,more='',act='')=>`<div class="section-head"><h2>${e(title)}</h2>${more?(act?`<button data-a="${act}">${e(more)}</button>`:`<span>${e(more)}</span>`):''}</div>`;
 const quick=(label,ic,act)=>`<button class="quick" data-a="${act}"><span class="quick-icon">${ico(ic)}</span>${e(label)}</button>`;
 const feature=(name,desc,ic,act)=>`<button class="feature-button card" data-a="${act}"><span class="ico">${ico(ic)}</span><span><strong>${e(name)}</strong><small>${e(desc)}</small></span></button>`;
 function eventMarkers(w,points){if(!w||!points.length)return '';return w.events.map((ev,i)=>{let n;if(w.mode==='demo')n=Math.min(points.length-1,Math.max(0,Math.floor((ev.time-w.started)/3500)+1));else{n=ev.point?w.points.findIndex(p=>p.time===ev.point.time):-1;if(n<0)n=points.length-1}let p=points[Math.min(n,points.length-1)];return `<g><circle cx="${p.x}" cy="${p.y}" r="10" fill="#e88d7c" stroke="#fff" stroke-width="2"/><text x="${p.x}" y="${p.y+3}" text-anchor="middle" font-size="9" font-family="sans-serif" font-weight="700" fill="#fff">${i+1}</text></g>`}).join('')}
 function mapBlock(mode='home',points=[],w=null){const poly=points.length>1?`<polyline points="${points.map(p=>`${p.x},${p.y}`).join(' ')}" stroke="#4b9b6c" stroke-width="4" stroke-linecap="round" stroke-linejoin="round" fill="none" stroke-dasharray="550" style="animation:draw 2s ease-out"/>`:'';return `<div class="map-card ${mode==='walk'?'walk-map':mode==='history'?'route-preview':''}"><svg class="map-svg" viewBox="0 0 360 230" preserveAspectRatio="none" aria-hidden="true"><rect width="360" height="230" fill="#e5efe1"/><path d="M-10 37C70 65 130-8 212 20s93 15 158-8M-10 164c78-15 122 37 207 5s106-20 180 6M86-10c-15 62 11 92-12 143s-9 81 9 109M252-10c-15 53 5 88 24 116s6 70-8 140" stroke="#fbfcf6" stroke-width="20"/><path d="M-10 37C70 65 130-8 212 20s93 15 158-8M-10 164c78-15 122 37 207 5s106-20 180 6M86-10c-15 62 11 92-12 143s-9 81 9 109M252-10c-15 53 5 88 24 116s6 70-8 140" stroke="#c9dcc6" stroke-width="1"/><path d="M5 118c50 4 88-10 136-45s84-13 115 11 74 25 112 5" stroke="#d3e5d0" stroke-width="13"/>${poly}${eventMarkers(w,points)}</svg><div class="map-top"><span class="map-loc">${ico('pin')}${mode==='home'?'附近的宠友':'路线记录'}</span><span class="map-badge">${mode==='home'?'示意地图 · 示例宠友':'示意底图 · 非真实地理位置'}</span></div>${mode==='home'?`<button class="pin p1" data-a="friend" data-v="0" aria-label="查看示例宠友山山"><img src="${asset['狗']}" alt=""></button><button class="pin p2" data-a="friend" data-v="1" aria-label="查看示例宠友栗子"><img src="${asset['猫']}" alt=""></button><button class="pin p3" data-a="friend" data-v="2" aria-label="查看示例宠友团团"><img src="${asset['兔']}" alt=""></button><span class="map-me"></span><button class="map-expand" data-a="map" aria-label="查看地图">${ico('expand')}</button>`:''}<span class="map-caption">${mode==='home'?'示意位置，不代表真实附近的人':'路线仅作形状展示，底图未接入'}</span></div>`}
 function dailyCard(){const done=data.daily?.date===today()&&data.daily?.petId===pet().id;const idea=pet().kind==='猫'?'陪它玩一会儿，留一个小瞬间':'和它出门走走，留一个小瞬间';return `<div class="daily-card"><span class="daily-icon">${ico('spark')}</span><span class="daily-copy"><small>今日陪伴小约定 · 本机记录</small><strong>${idea}</strong></span><button class="daily-done ${done?'is-done':''}" data-a="daily-toggle" aria-pressed="${done}">${done?'已完成 ✓':'记一笔'}</button></div>`}
 function renderHome(){return shell(`<div class="wrap"><div class="top"><div><div class="brand">拍爪<i></i></div><div class="top-sub">和小伙伴一起，认识新朋友</div></div><div class="top-actions"><button class="icon-button" data-a="messages" aria-label="消息">${ico('bell')}</button></div></div>${mapBlock()}<button class="walk-cta press" data-a="walk-setup"><span class="round">${ico('route')}</span><span><strong>一起出去遛遛</strong><small>选择小伙伴，记录今天的路线</small></span><span class="arr">↗</span></button>${dailyCard()}${sec('为你准备','探索宠物生活')}<div class="quick-grid">${quick('遛宠记录','history','routes')}${quick('宠物主页','paw','pet-home')}${quick('共享小窝','house','nest')}${quick('领养专区','heart','adoption')}</div>${sec('遇见附近宠友','示例资料')}<div class="friends">${[['山山','金毛 · 爱散步','狗'],['栗子','猫咪 · 慢热','猫'],['团团','兔子 · 喜欢草','兔']].map((x,i)=>`<button class="friend" data-a="friend" data-v="${i}"><img src="${asset[x[2]]}" alt=""><strong>${x[0]} <i>· 示例</i></strong><small>${x[1]}</small></button>`).join('')}</div><p class="near-note">这里展示的是虚构示例；本原型不会获取或公开他人位置。</p>${sec('发现宠物好物','商家展示示例')}<button class="shop-entry" data-a="shop"><span class="shop-entry-icon">${ico('bag')}</span><span><strong>好物与友好服务</strong><small>为宠物生活，发现更多选择</small></span><span class="arr">↗</span></button>${sec('陪伴再多一点')}<div class="feature-row"><button class="feature-tile" data-a="ai-chat"><strong>AI 健康咨询 ↗</strong><small>先了解，再寻求专业帮助</small></button><button class="feature-tile" data-a="portrait"><strong>给它画张像 ↗</strong><small>看看专属画像示例</small></button></div></div>`)}
 function postList(){return [...data.posts,...examples]}
 function postCard(p){let liked=data.likes.includes(p.id);return `<article class="post card" role="button" tabindex="0" data-a="post-detail" data-id="${e(p.id)}" aria-label="查看${e(p.title)}"><img src="${e(p.image)}" alt="${e(p.pet)}的示意图片"><div class="post-body"><h3>${e(p.title)}</h3><div class="post-author"><img src="${e(p.image)}" alt=""><span>${e(p.author)}</span><span>♡ ${(p.likes||0)+(liked?1:0)}</span></div></div></article>`}
 function renderCommunity(){let ps=postList();if(filter==='猫咪')ps=ps.filter(x=>x.animal==='猫');if(filter==='狗狗')ps=ps.filter(x=>x.animal==='狗');if(filter==='其他')ps=ps.filter(x=>!['猫','狗'].includes(x.animal));if(filter==='关注')ps=ps.filter(x=>data.follows.includes(x.author));return shell(`<div class="wrap"><div class="top"><div><h1 class="title">宠友社区</h1><p class="sub">每个小伙伴，都有自己的故事</p></div><button class="icon-button" data-a="messages" aria-label="消息">${ico('bell')}</button></div><div class="topic-strip"><div><small>THIS WEEK · 本周话题</small><strong>晒晒我家午睡选手</strong></div><button data-a="topic">我也参与</button></div>${sec('发现有趣的它们','内容为演示')}<div class="chip-row">${['推荐','关注','猫咪','狗狗','其他'].map(x=>`<button class="chip ${filter===x?'on':''}" data-a="filter" data-v="${x}">${x}</button>`).join('')}</div>${ps.length?`<div class="feed-grid">${ps.map(postCard).join('')}</div>`:'<div class="empty">还没有关注的内容<br>先去看看推荐吧</div>'}</div>`)}
 function renderCare(){const p=pet(),next=[...data.health].filter(x=>(x.petId||'demo')===p.id).sort((a,b)=>a.date.localeCompare(b.date)).filter(x=>!x.done).slice(0,2);return shell(`<div class="wrap"><div class="top"><div><h1 class="title">陪伴与养护</h1><p class="sub">把每一次照顾，都好好记下来</p></div><button class="icon-button" data-a="health-history" aria-label="养护记录">${ico('care')}</button></div>${petSelector()}<div class="pet-card card"><div class="pet-top"><img class="avatar" src="${petPhoto(p)}" alt=""><div><h3>${e(p.name)} ${p.demo?'<span class="tiny">示例</span>':''}</h3><p>${e(p.kind)} · ${e(p.age||'年龄未填写')}</p></div><span class="tag">日常健康档案</span></div><div class="bar"><button data-a="health-form" data-v="疫苗">疫苗记录</button><button data-a="health-form" data-v="驱虫">驱虫记录</button><button data-a="health-form" data-v="洗澡">洗澡记录</button></div></div>${sec('今天的照顾','本机记录')}<div class="card" style="padding:0 14px">${next.length?next.map(x=>`<div class="timeline-row"><div class="timeline-date">${e(x.date.slice(5))}</div><div><strong>${e(x.type)}</strong><small>${e(x.note||'照顾小伙伴')} ${x.cycle?`· 每 ${x.cycle} 天`:''}</small></div><button data-a="done-health" data-id="${e(x.id)}">完成</button></div>`).join(''):`<div class="empty">还没有提醒<br>添加一次疫苗、驱虫或洗澡记录</div>`}</div><p class="fine">原型可记录周期并计算下一次日期，不会发送系统通知。</p>${sec('科学养宠')}<div class="feature-list">${feature('健康时光机','日历与护理记录','care','health-history')}${feature('护理技巧','日常养护小知识','bath','tips')}${feature('AI 健康咨询','问诊界面演示','medical','ai-chat')}${feature('品种识别','识别界面演示','breed','breed')}</div></div>`)}
 function renderProfile(){const p=pet();return shell(`<div class="wrap"><div class="top"><div><h1 class="title">我的</h1><p class="sub">这里留给你和你的伙伴</p></div><button class="icon-button" data-a="settings" aria-label="设置">${ico('shield')}</button></div><div class="pet-hero"><img class="pet-photo" src="${petPhoto(p)}" alt=""><div><h2>${e(p.name)} ${p.demo?'<span class="tiny">示例</span>':''}</h2><p>${e(p.kind)} · ${e(p.age||'年龄未填写')} · ${e(p.sterilized||'未填写')}</p></div><button class="icon-button pet-edit" data-a="pet-form" aria-label="编辑宠物">${ico('edit')}</button></div><div class="pet-stats card"><div><strong>${data.posts.length}</strong><span>动态</span></div><div><strong>${data.walks.length}</strong><span>遛宠</span></div><div><strong>${data.saved.length}</strong><span>收藏</span></div></div>${!data.registered?'<div class="notice warm">当前为游客体验，创建的是本机演示档案。<button class="text-link" data-a="login" style="margin-left:6px">体验注册 →</button></div>':''}${sec('我的小伙伴')}<div class="card" style="padding:0 14px"><button class="wide-action" data-a="pet-home">${ico('paw')}<span><strong>专属主页与相册</strong><small>动态和照片，记录它的成长</small></span><span class="arr">›</span></button><button class="wide-action" data-a="nest">${ico('house')}<span><strong>共享小窝</strong><small>邀请家人，共同照顾小伙伴</small></span><span class="arr">›</span></button><button class="wide-action" data-a="routes">${ico('route')}<span><strong>遛宠足迹</strong><small>回看每一次出门</small></span><span class="arr">›</span></button></div>${sec('更多功能')}<div class="feature-list">${feature('宠物画像','创意图片示例','spark','portrait')}${feature('品种识别','识别流程示例','breed','breed')}${feature('领养专区','为小家伙寻找家','heart','adoption')}${feature('好物空间','商业板块预留','bag','shop')}</div><p class="fine" style="margin-top:17px">所有个人内容目前仅保存在当前浏览器，不会同步或上传。</p></div>`)}
 function renderPetHome(){const p=pet(),mine=data.posts.filter(x=>x.petId===p.id||(!x.petId&&x.pet===p.name));let images=[...(p.photo?[p.photo]:[]),...mine.map(x=>x.image),...data.walks.filter(w=>w.petId===p.id||(!w.petId&&w.petName===p.name)).flatMap(w=>w.events.filter(z=>z.image).map(z=>z.image))].filter(Boolean);if(!images.length)images=[petPhoto(p)];return shell(`<div class="wrap">${head('宠物的专属主页')}<div class="pet-hero"><img class="pet-photo" src="${petPhoto(p)}" alt=""><div><h2>${e(p.name)} ${p.demo?'<span class="tiny">示例宠物</span>':''}</h2><p>${e(p.kind)} · ${e(p.age||'年龄未填写')} · 绝育：${e(p.sterilized||'未填写')}</p></div><button class="icon-button pet-edit" data-a="pet-form" aria-label="编辑档案">${ico('edit')}</button></div><div class="notice">宠物数字身份证：展示档案、生活动态和相册。正式版可扩展宠物视角发布。</div><div class="pet-stats"><div><strong>${mine.length}</strong><span>动态</span></div><div><strong>${images.length}</strong><span>照片</span></div><div><strong>${data.walks.filter(w=>w.petId===p.id||(!w.petId&&w.petName===p.name)).length}</strong><span>足迹</span></div></div><div class="feature-row"><button class="feature-tile" data-a="compose"><strong>记录此刻 ↗</strong><small>照片会进入本机相册</small></button><button class="feature-tile" data-a="nest"><strong>共享小窝 ↗</strong><small>和家人一起照顾</small></button></div>${sec('时光相册','保存在当前设备')}<div class="album-grid">${images.map(x=>`<img src="${e(x)}" alt="宠物相册照片">`).join('')}</div>${sec('它的动态','本机内容')}${mine.length?`<div class="feed-grid">${mine.map(postCard).join('')}</div>`:'<div class="empty">还没有动态，分享一个日常瞬间吧</div>'}</div>`,false)}
 function renderLogin(){return shell(`<div class="wrap auth-form">${head('体验注册')}<h1 class="auth-title">开启属于你们的<br>拍爪生活。</h1><p class="auth-desc">使用演示号码体验流程，无需提供真实手机号。<br>本原型不会发送短信或创建真实账户。</p><div class="field"><label for="phone">演示手机号</label><input id="phone" value="13800000000" readonly></div><div class="field"><label for="code">体验验证码</label><input id="code" inputmode="numeric" maxlength="6" placeholder="输入 123456"></div><div class="notice">体验验证码：<strong>123456</strong></div><label class="agreement"><input type="checkbox" id="agree"><span>我知道这是本机体验原型，内容不会上传。</span></label><button class="primary" data-a="login-next">继续，填写宠物资料</button><button class="secondary" style="margin-top:10px" data-a="skip-login">暂不注册，先逛逛</button></div>`,false)}
 function renderPetForm(){const p=petDraft;return shell(`<div class="wrap">${head(data.registered?'宠物资料':'添加小伙伴')}<p class="sub">先从猫猫狗狗开始，其他小伙伴也可以建档。</p><div class="form"><div class="field"><label>宠物头像（选填）</label><label class="upload" for="pet-upload" style="height:95px">${p.photo?`<img src="${e(p.photo)}" alt="已选宠物头像">`:`${ico('camera')} 选择一张照片`}</label><input id="pet-upload" type="file" accept="image/*" hidden></div><div class="field"><label for="pet-name">宠物名称</label><input id="pet-name" value="${e(p.name||'')}" maxlength="16" placeholder="例如：奶豆"></div><div class="field"><label>宠物种类</label><div class="choice-row">${['狗','猫','其他'].map(x=>`<button class="${selectedPet===x?'active':''}" data-a="select-pet" data-v="${x}">${x==='其他'?'其他伙伴':x==='狗'?'狗狗':'猫猫'}</button>`).join('')}</div></div><div class="field-grid"><div class="field"><label for="pet-age">年龄（选填）</label><input id="pet-age" value="${e(p.age||'')}" maxlength="12" placeholder="例如：2岁"></div><div class="field"><label for="pet-type">${selectedPet==='其他'?'具体种类':'品种'}（选填）</label><input id="pet-type" value="${e(p.breed||'')}" maxlength="20" placeholder="${selectedPet==='其他'?'例如：鹦鹉、龟':'例如：中华田园猫'}"></div></div><div class="field"><label>是否绝育（选填）</label><div class="choice-row">${['未填写','已绝育','未绝育'].map(x=>`<button class="${sterilized===x?'active':''}" data-a="sterilized" data-v="${x}">${x}</button>`).join('')}</div></div><p class="age-hint">照片仅保存在本机，建议小于 2 MB。不确定的项目可以留空。</p><button class="primary" data-a="save-pet">保存，进入拍爪</button><button class="secondary" style="margin-top:10px" data-a="skip-login">暂时没有宠物，先逛逛</button></div></div>`,false)}
 function renderCompose(){return shell(`<div class="wrap">${head('分享生活','发布','submit-post')}<p class="sub">用你的视角，或用小伙伴的口吻记录今天</p>${topic?`<div class="notice" style="margin-top:13px">参与话题：# ${e(topic)}</div>`:''}<div class="field"><label>选择发布视角</label><div class="choice-row"><button class="${voice==='owner'?'active':''}" data-a="voice" data-v="owner" aria-pressed="${voice==='owner'}">我的视角</button><button class="${voice==='pet'?'active':''}" data-a="voice" data-v="pet" aria-pressed="${voice==='pet'}">以宠物口吻</button></div></div><div class="field"><label for="post-text">想分享什么？</label><textarea id="post-text" maxlength="200" placeholder="今天的小伙伴有什么趣事？"></textarea></div><label class="upload" for="upload">${imageData?`<img src="${imageData}" alt="已选照片">`:`${ico('camera')} 添加一张照片`}</label><input id="upload" type="file" accept="image/*" hidden><p class="fine">不选照片会显示示意图；照片与文字只保存在当前设备，单张不超过 2 MB。</p><div class="card" style="padding:0 14px"><button class="wide-action" data-a="pet-home">${ico('paw')}<span><strong>关联 ${e(pet().name)}</strong><small>照片会加入本机相册</small></span><span class="arr">›</span></button><div class="wide-action">${ico('shield')}<span><strong>仅本机演示</strong><small>不会发布给其他人</small></span></div></div></div>`,false)}
 function renderDetail(){const p=postList().find(x=>x.id===detailId);if(!p){view='community';return renderCommunity()}let comments=data.comments[p.id]||[];return shell(`<div class="wrap">${head('动态详情')}<img class="detail-img" src="${e(p.image)}" alt="宠物照片"><div class="detail-author"><img class="avatar" src="${e(p.image)}" alt=""><div><strong>${e(p.author)}</strong><small>分享了小伙伴的日常</small></div>${!p.mine&&p.author!=='我'?`<button data-a="follow" data-v="${e(p.author)}">${data.follows.includes(p.author)?'已关注':'＋ 关注'}</button>`:''}</div><h2 class="detail-title">${e(p.title)}</h2><p class="detail-copy">${e(p.text)}</p><div class="detail-tools"><button data-a="like">${ico('heart')}${data.likes.includes(p.id)?'已喜欢':'喜欢'}</button><button data-a="save-post">${ico('bookmark')}${data.saved.includes(p.id)?'已收藏':'收藏'}</button><button data-a="report">${ico('more')}举报</button></div>${sec('回应 '+comments.length,'保存在本机')}${comments.length?comments.map(x=>`<div class="timeline-row"><img class="avatar" src="${petPhoto()}" alt=""><div><strong>我</strong><small style="font-size:11px;line-height:1.5">${e(x)}</small></div></div>`).join(''):'<p class="fine">还没有回应，留下第一句友好的话吧。</p>'}<div class="comment-input"><input id="comment" maxlength="120" placeholder="说点友好的话…"><button data-a="comment">发送</button></div></div>`,false)}
 function renderNest(){return shell(`<div class="wrap">${head('共享小窝')}<div class="pet-card card"><div class="pet-top"><img class="avatar" src="${petPhoto()}" alt=""><div><h3>${e(pet().name)} 的小窝</h3><p>一起照顾，共同记录</p></div><span class="tag">体验演示</span></div></div><div class="notice warm">目前没有服务器和其他真实用户，邀请与多人共享仅展示未来流程。</div>${sec('小窝成员','示例')}<div class="card" style="padding:0 14px"><div class="wide-action">${ico('user')}<span><strong>我</strong><small>小窝创建者</small></span><span class="arr">管理员</span></div><div class="wide-action">${ico('friends')}<span><strong>家人 / 伴侣 / 室友</strong><small>未来可共同维护档案和相册</small></span></div></div>${sec('共享什么')}<div class="feature-list">${feature('时光相册','共同查看生活照片','album','pet-home')}${feature('护理记录','一起记录照顾事项','care','health-history')}</div><button class="primary" style="margin-top:22px" data-a="invite">生成邀请示例</button><div id="invite-result"></div></div>`,false)}
 function renderAdoption(){return shell(`<div class="wrap">${head('领养专区')}<div class="topic-strip"><div><small>ADOPT WITH LOVE</small><strong>等一个温暖的家</strong><p class="fine" style="margin:7px 0 0">每一段相遇，都值得被认真对待。</p></div>${ico('heart')}</div><div class="notice warm" style="margin-top:12px">以下为虚构展示，不是真实待领养信息，也不能联系领养人。</div>${sec('寻找小伙伴','示例资料')}${adopt.map(a=>`<div class="adoption-card card"><img src="${e(a.image)}" alt=""><div class="body"><strong>${e(a.name)}</strong><p>${e(a.kind)} · ${e(a.age)}</p><span class="tag">${e(a.place)}</span><br><button data-a="adopt-detail" data-id="${e(a.id)}">了解领养 →</button></div></div>`).join('')}</div>`,false)}
 function renderAdoptionDetail(){const a=adopt.find(x=>x.id===adoptionId)||adopt[0];return shell(`<div class="wrap">${head('领养详情')}<img class="detail-img" src="${a.image}" alt=""><h2 class="detail-title">${e(a.name)} 正在等一个家</h2><p class="sub">${e(a.kind)} · ${e(a.age)} · ${e(a.place)}</p><p class="detail-copy">${e(a.text)}</p><div class="notice warm">这是虚构示例。正式领养需核验信息、线下见面，并警惕以运费等名义要求提前付款。</div><div class="field"><label for="adopt-note">给它留一句话（演示）</label><textarea id="adopt-note" maxlength="150" placeholder="说说你希望怎样照顾它"></textarea></div><button class="primary" data-a="adopt-apply">保存领养意向示例</button><p class="fine">仅保存到当前设备，不会发送给任何人。</p></div>`,false)}
 function renderHealthForm(){let typ=window.pendingType||'疫苗';return shell(`<div class="wrap">${head('添加养护记录')}<p class="sub">记录照顾事项，可选择是否按周期重复。</p><div class="form"><div class="field"><label for="health-type">记录类型</label><select id="health-type">${['疫苗','驱虫','洗澡','体重','领养纪念日','其他'].map(x=>`<option ${x===typ?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label for="health-date">日期</label><input id="health-date" type="date" value="${today()}"></div><div class="field"><label for="health-cycle">重复周期</label><select id="health-cycle"><option value="0">单次，不重复</option><option value="7">每 7 天</option><option value="14">每 14 天</option><option value="30">每 30 天</option><option value="90">每 90 天</option><option value="365">每 365 天</option></select></div><div class="field"><label for="health-note">备注 / 体重数值（选填）</label><input id="health-note" maxlength="50" placeholder="例如：洗澡，或体重 5.2 kg"></div><div class="notice">护理和疫苗周期请按宠物实际情况与兽医建议填写；原型不会自动判断周期或发送通知。</div><button class="primary" style="margin-top:17px" data-a="save-health">保存记录</button></div></div>`,false)}
 function miniCalendar(){const now=new Date(),first=new Date(now.getFullYear(),now.getMonth()+calendarOffset,1),y=first.getFullYear(),m=first.getMonth(),prefix=`${y}-${String(m+1).padStart(2,'0')}-`,days=new Date(y,m+1,0).getDate(),start=(first.getDay()+6)%7,marked=new Set(data.health.filter(x=>(x.petId||'demo')===pet().id).map(x=>x.date));let cells=Array(start).fill('<span></span>');for(let d=1;d<=days;d++){let date=prefix+String(d).padStart(2,'0');cells.push(`<button class="cal-day ${date===calendarFilter?'selected':''} ${date===today()?'today':''} ${marked.has(date)?'marked':''}" data-a="calendar-day" data-v="${date}" aria-label="${date}">${d}</button>`)}return `<div class="calendar card"><div class="calendar-head"><button data-a="month" data-v="-1" aria-label="上个月">‹</button><strong>${y} 年 ${m+1} 月</strong><button data-a="month" data-v="1" aria-label="下个月">›</button></div><div class="calendar-grid weekdays">${['一','二','三','四','五','六','日'].map(x=>`<span>${x}</span>`).join('')}</div><div class="calendar-grid">${cells.join('')}</div><p class="fine">圆点表示有记录；点击日期查看当天。</p></div>`}
 function renderHealthHistory(){let items=[...data.health].filter(x=>(x.petId||'demo')===pet().id&&(!calendarFilter||x.date===calendarFilter)).sort((a,b)=>b.date.localeCompare(a.date));return shell(`<div class="wrap">${head('健康时光机','添加','health-form')}<div class="topic-strip"><div><small>CARE TIMELINE</small><strong>${e(pet().name)} 的照顾日历</strong><p class="fine" style="margin:7px 0 0">疫苗、驱虫、洗澡和纪念日，慢慢记。</p></div>${ico('care')}</div>${miniCalendar()}<p class="fine">记录仅保存在当前浏览器；重复事项完成后，会生成下一次日期。</p>${sec(calendarFilter?calendarFilter+' 的记录':'时间轴',calendarFilter?'查看全部':items.length+' 条本机记录',calendarFilter?'clear-calendar':'')}<div class="card" style="padding:0 14px">${items.length?items.map(x=>`<div class="timeline-row"><div class="timeline-date">${e(x.date)}</div><div><strong>${e(x.type)} ${x.done?'· 已完成':''}</strong><small>${e(x.note||'日常照顾')} ${x.cycle?`· 每 ${x.cycle} 天`:''}</small></div>${x.done?'':`<button data-a="done-health" data-id="${e(x.id)}">完成</button>`}</div>`).join(''):'<div class="empty">当前没有记录<br>点击右上角添加</div>'}</div><button class="secondary" style="margin-top:16px" data-a="health-form">＋ 添加记录</button><p class="fine">这是一份体验记录，不会同步云端或触发系统提醒。</p></div>`,false)}
 function renderTips(){return shell(`<div class="wrap">${head('日常护理技巧')}<div class="notice">以下为原型中的基础提示，不替代兽医针对具体宠物的建议。</div><button class="article" data-a="tip-detail" data-v="洗护"><strong>洗护小习惯</strong><p>根据物种、皮肤状况和兽医建议安排清洁，选择适合宠物的用品。</p></button><button class="article" data-a="tip-detail" data-v="疫苗"><strong>疫苗与驱虫</strong><p>用档案记下日期与产品信息，具体方案请咨询兽医。</p></button><button class="article" data-a="tip-detail" data-v="体重"><strong>观察体重与状态</strong><p>定期记录变化，出现明显异常时联系兽医。</p></button><button class="article" data-a="tip-detail" data-v="出行"><strong>一起安全出门</strong><p>根据宠物的习性和环境准备安全措施，保持饮水与休息。</p></button></div>`,false)}
 function renderAiChat(){let messages=data.chat||[];return shell(`<div class="wrap">${head('AI 健康咨询')}<div class="notice warm">体验界面：未接入 AI 或兽医。内容不构成诊断、处方或治疗建议；如宠物出现明显异常，请及时联系兽医。</div><div class="chat-box"><div class="chat-bubble">你好，可以在这里记录你想咨询的问题。正式版是否接入 AI 和兽医服务仍待确认。</div>${messages.map(x=>`<div class="chat-bubble ${x.role==='me'?'me':''}">${e(x.text)}</div>`).join('')}</div><div class="comment-input"><input id="chat-input" maxlength="150" placeholder="描述你想咨询的问题"><button data-a="chat-send">发送</button></div><p class="fine">演示问题只保存在当前浏览器，不会被专业人员接收。</p></div>`,false)}
 function renderPortrait(){const image=artType==='猫'?'assets/cat-art.webp':'assets/dog-art.webp';return shell(`<div class="wrap">${head('AI 宠物画像')}<p class="sub">让每个小伙伴，都有一张专属肖像</p><div class="choice-row" style="margin:16px 0">${['狗','猫'].map(x=>`<button class="${artType===x?'active':''}" data-a="art-type" data-v="${x}">${x==='狗'?'狗狗示例':'猫猫示例'}</button>`).join('')}</div><img class="ai-img" src="${image}" alt="宠物画像示例"><div class="ai-demo">这是提前制作的 AI 画像示例，并未识别或生成你家宠物的画像。正式版需接入模型并单独评估成本。</div><button class="primary" data-a="portrait-demo">查看生成流程说明</button></div>`,false)}
 function renderBreed(){return shell(`<div class="wrap">${head('宠物品种识别')}<p class="sub">上传照片，看看未来的识别流程。</p><label class="upload" for="breed-upload" style="margin-top:20px;height:220px">${imageData?`<img src="${imageData}" alt="已选择宠物照片">`:`${ico('camera')} 选择宠物照片`}</label><input id="breed-upload" type="file" accept="image/*" hidden><p class="fine">图片仅保存在当前页面，不会上传。支持选择不超过 2 MB 的图片。</p><div class="notice warm">这里仅展示品种识别的交互，未接入识别模型，不会对上传图片给出真实判断。</div><button class="primary" style="margin-top:18px" data-a="breed-demo">查看识别示例</button><div id="breed-result"></div></div>`,false)}
 const shopItems=[
  {id:'s1',category:'用品',name:'日常出行小装备',merchant:'森野宠物 · 虚构商家',desc:'为每一次出门准备舒适与安心。',icon:'route',tone:'mint'},
  {id:'s2',category:'用品',name:'猫咪玩耍灵感',merchant:'小爪生活 · 虚构商家',desc:'给好奇的它，一点有趣的陪伴。',icon:'spark',tone:'peach'},
  {id:'s3',category:'服务',name:'宠物友好空间',merchant:'邻里小屋 · 虚构商家',desc:'发现欢迎小伙伴的线下好去处。',icon:'house',tone:'lavender'}
 ];
 function renderShop(){let items=shopFilter==='全部'?shopItems:shopItems.filter(x=>x.category===shopFilter);return shell(`<div class="wrap">${head('好物与友好服务')}<div class="market-hero"><div><span>PAIZHUA FOR PET LIFE</span><h2>让陪伴，<br>多一些好选择。</h2><p>发现宠物好物与友好服务</p></div><div class="market-hero-art">${ico('bag')}<i>✳</i></div></div><div class="market-note">以下商家与商品均为虚构展示，不提供购买或真实推广。</div><div class="market-heading"><div><small>DISCOVER</small><h2>为你发现</h2></div><button data-a="merchant">商家入驻 <span>↗</span></button></div><div class="chip-row market-filters">${['全部','用品','服务'].map(x=>`<button class="chip ${shopFilter===x?'on':''}" data-a="shop-filter" data-v="${x}" aria-pressed="${shopFilter===x}">${x}</button>`).join('')}</div><div class="market-grid">${items.map(x=>`<button class="market-item card" data-a="shop-detail" data-id="${x.id}"><div class="market-art ${x.tone}"><span class="ad-label">广告 · 示例</span>${ico(x.icon)}<i>✳</i></div><div class="market-item-copy"><strong>${x.name}</strong><small>${x.merchant}</small><span>查看展示 <b>↗</b></span></div></button>`).join('')}</div><div class="merchant-banner"><div><span>FOR MERCHANTS</span><strong>与你一起，照顾好它们</strong><small>展示宠物好物，连接有共同爱好的宠友</small></div><button data-a="merchant" aria-label="了解商家入驻">↗</button></div><p class="fine">未来实际投放的广告需清楚标识，并经商家资质和内容审核。当前为界面演示。</p></div>`,false)}
 function renderShopDetail(){const x=shopItems.find(z=>z.id===shopItemId)||shopItems[0];return shell(`<div class="wrap">${head('好物展示')}<div class="market-detail-art market-art ${x.tone}"><span class="ad-label">广告 · 示例</span>${ico(x.icon)}<i>✳</i></div><div class="market-detail-copy"><span class="tag">${x.category} · 虚构示例</span><h2>${x.name}</h2><p>${x.desc}</p><div class="market-merchant">${ico('bag')}<span><strong>${x.merchant}</strong><small>商家资料展示示意</small></span></div></div><div class="notice warm">该商品、商家及推广信息均为示例；没有真实购买、联系或支付功能。</div><button class="secondary" style="margin-top:16px" data-a="shop-back">返回发现好物</button></div>`,false)}
 function renderMerchant(){return shell(`<div class="wrap">${head('商家入驻')}<div class="merchant-head"><span>PAIZHUA PARTNERS</span><h2>和拍爪一起，<br>认真对待每份陪伴。</h2><p>为宠物用品、友好门店和服务预留展示空间。</p></div><div class="notice warm">入驻流程仅供体验，信息只保存在当前浏览器，不会发送给平台，也不会创建店铺。请勿填写真实联系方式或证件资料。</div>${sec('未来合作流程','示例')}<div class="merchant-steps"><div><b>01</b><span><strong>填写基本资料</strong><small>了解商家与服务类别</small></span></div><div><b>02</b><span><strong>资质与内容审核</strong><small>正式开放时核验相关资料</small></span></div><div><b>03</b><span><strong>展示与推广</strong><small>通过后按约定展示，并标识广告</small></span></div></div>${sec('体验入驻表单','本机演示')}<div class="field"><label for="merchant-name">商家名称示例</label><input id="merchant-name" maxlength="30" placeholder="例如：小爪生活馆"></div><div class="field"><label for="merchant-type">经营类别</label><select id="merchant-type"><option>宠物用品</option><option>宠物友好门店</option><option>宠物服务</option><option>其他</option></select></div><button class="primary" data-a="merchant-save">保存入驻示例</button><p class="fine">暂不收集手机号、营业执照、证件或支付信息。</p></div>`,false)}
 function renderMessages(){return shell(`<div class="wrap">${head('消息')}<div class="notice">这是演示消息，不会收到真实用户的回复。</div><div class="card" style="padding:0 14px;margin-top:14px"><div class="wide-action">${ico('heart')}<span><strong>互动消息</strong><small>点赞、评论与关注会出现在这里</small></span><span class="arr">示例</span></div><div class="wide-action">${ico('paw')}<span><strong>拍爪小助手</strong><small>欢迎来到拍爪，一起认识新朋友</small></span><span class="arr">示例</span></div></div><div class="empty">从一次拍爪开始，认识新朋友</div></div>`,false)}
 function renderFriend(){const i=Number(window.friendIndex||0),friends=[{name:'山山',kind:'金毛',img:asset['狗'],desc:'爱散步，也喜欢在草地发呆。'},{name:'栗子',kind:'猫咪',img:asset['猫'],desc:'喜欢阳光和安静的午后。'},{name:'团团',kind:'兔子',img:asset['兔'],desc:'喜欢新鲜的草和舒服的小窝。'}],f=friends[i]||friends[0];return shell(`<div class="wrap">${head('宠友资料')}<img class="detail-img" src="${f.img}" alt=""><div class="pet-hero"><div><h2>${f.name} <span class="tiny">虚构示例</span></h2><p>${f.kind} · 宠友资料演示</p></div><button class="secondary" style="margin-left:auto;width:94px" data-a="hello">打个招呼</button></div><p class="detail-copy">${f.desc}</p><div class="notice">这是虚构的宠物资料，不代表真实附近的人，也无法发送真实消息。</div></div>`,false)}
 function renderSettings(){return shell(`<div class="wrap">${head('设置与隐私')}<div class="notice warm">本原型没有真实账号或服务器。演示资料与路线保存在当前浏览器，清除浏览器数据可能丢失。</div><div class="card" style="padding:0 14px;margin-top:14px"><button class="wide-action" data-a="privacy-info">${ico('shield')}<span><strong>位置与隐私</strong><small>定位需主动选择并授权</small></span><span class="arr">›</span></button><button class="wide-action" data-a="clear-data">${ico('trash')}<span><strong>清除本机体验数据</strong><small>删除当前浏览器中的演示资料</small></span><span class="arr">›</span></button></div></div>`,false)}
 const demoPath=[{x:45,y:171},{x:75,y:163},{x:102,y:149},{x:125,y:129},{x:150,y:116},{x:178,y:110},{x:202,y:98},{x:229,y:91},{x:257,y:102},{x:283,y:125}];
 function visualPoints(w){if(w.mode==='demo')return demoPath.slice(0,Math.max(2,Math.min(demoPath.length,Math.floor(((w.ended||Date.now())-w.started)/3500)+2)));if(!w.points.length)return[];let lats=w.points.map(p=>p.lat),lngs=w.points.map(p=>p.lng),loX=Math.min(...lngs),hiX=Math.max(...lngs),loY=Math.min(...lats),hiY=Math.max(...lats),spanX=hiX-loX||.0001,spanY=hiY-loY||.0001;return w.points.map(p=>({x:40+(p.lng-loX)/spanX*270,y:190-(p.lat-loY)/spanY*140}))}
 function elapsed(w){let s=Math.max(0,Math.floor(((w.ended||Date.now())-w.started)/1000));return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}
 function meters(w){if(w.mode==='demo')return Math.min(180,Math.floor(((w.ended||Date.now())-w.started)/1000)*5);let m=0;for(let i=1;i<w.points.length;i++)m+=distance(w.points[i-1],w.points[i]);return Math.round(m)}
 function distance(a,b){let rad=n=>n*Math.PI/180, R=6371000, d1=rad(b.lat-a.lat),d2=rad(b.lng-a.lng);let h=Math.sin(d1/2)**2+Math.cos(rad(a.lat))*Math.cos(rad(b.lat))*Math.sin(d2/2)**2;return R*2*Math.atan2(Math.sqrt(h),Math.sqrt(1-h))}
 function renderWalkSetup(){const p=pet();return shell(`<div class="wrap">${head('一起去遛宠')}<div class="pet-card card"><div class="pet-top"><img class="avatar" src="${petPhoto(p)}" alt=""><div><h3>带 ${e(p.name)} 出门</h3><p>${p.demo?'示例宠物，可创建自己的档案':e(p.kind)+' · 今天也一起散步吧'}</p></div><button class="tag" data-a="pet-form">更换 / 创建</button></div></div><div class="notice">路线默认仅保存在当前浏览器，不会展示给其他人。结束后可以回看或删除。</div>${sec('选择体验方式')}<div class="card" style="padding:0 14px"><div class="wide-action">${ico('route')}<span><strong>演示遛宠路线</strong><small>不获取位置，用示例路线体验完整流程。</small></span></div><div class="wide-action">${ico('pin')}<span><strong>试用真实定位</strong><small>仅在你点击并授权后记录位置；需要浏览器支持。</small></span></div></div><button class="primary" style="margin-top:18px" data-a="walk-demo">开始演示遛宠</button><button class="secondary" style="margin-top:10px" data-a="walk-real">尝试真实定位记录</button><p class="fine">真实定位仅在页面保持打开且浏览器允许时尝试记录；地图背景为示意图，不显示真实街道。浏览器或系统可能不支持本地页面定位，也不保证后台持续记录。</p></div>`,false)}
 function renderWalk(){if(!walk){view='walk-setup';return renderWalkSetup()}let w=walk;return shell(`<div class="wrap">${head('正在和 '+w.petName+' 出门')}<div class="notice ${w.mode==='demo'?'warm':''}">${w.mode==='demo'?'演示路线和距离均为模拟，不是你的实际运动数据。':'正在尝试前台定位记录；轨迹仅保存在本机，底图为示意。'}</div>${mapBlock('walk',visualPoints(w),w)}<div class="walk-info"><img class="avatar" src="${asset[w.petKind]||asset['其他']}" alt=""><span><strong>${e(w.petName)} 的遛宠时光</strong><small>留下途中每个小瞬间</small></span><span class="mode">${w.mode==='demo'?'演示模式':'定位模式'}</span></div><div class="stats"><div><strong id="walk-time">${elapsed(w)}</strong><small>时长</small></div><div><strong id="walk-distance">${(meters(w)/1000).toFixed(2)}</strong><small>${w.mode==='demo'?'模拟公里':'记录公里'}</small></div><div><strong id="walk-events">${w.events.length}</strong><small>沿途打卡</small></div></div>${sec('沿途记一笔','仅本机')}<div class="action-row"><button class="mini-action" data-a="walk-event" data-v="上厕所"><span>${ico('mark')}</span>上厕所</button><button class="mini-action" data-a="walk-event" data-v="喝水"><span>${ico('water')}</span>喝水</button><button class="mini-action" data-a="walk-event" data-v="交友"><span>${ico('friends')}</span>交友</button><label class="mini-action" for="walk-photo"><span>${ico('camera')}</span>拍照</label><input id="walk-photo" type="file" accept="image/*" hidden></div><div id="walk-event-list">${w.events.length?`<p class="fine">已记录：${w.events.map((x,i)=>(i+1)+' '+e(x.type)).join('、')}</p>`:'<p class="fine">记录下途中发生的小事。</p>'}</div><div class="walk-controls"><button class="primary" data-a="finish-walk">结束并保存</button></div><p class="fine">示意底图不可导航。结束前刷新或关闭页面可能丢失本次记录。</p></div>`,false)}
 function renderRoutes(){let routes=[...data.walks].reverse();return shell(`<div class="wrap">${head('遛宠足迹')}<div class="topic-strip"><div><small>WALK MEMORIES</small><strong>每一次出门都值得记住</strong><p class="fine" style="margin:7px 0 0">时长、路线和沿途打卡都在这里。</p></div>${ico('route')}</div><p class="fine">路线仅保存在本机。演示路线不是真实定位；地图底图为示意。</p>${sec('历史路线',routes.length+' 次记录')}<div class="route-list">${routes.length?routes.map(w=>`<button class="route-item card" data-a="route-detail" data-id="${e(w.id)}"><span class="route-icon">${ico('route')}</span><span><strong>${e(w.petName)} 的${w.mode==='demo'?'演示':'定位'}遛宠</strong><small>${e(new Date(w.started).toLocaleString('zh-CN'))} · ${elapsed(w)} · ${(meters(w)/1000).toFixed(2)} km</small></span><span class="arr">›</span></button>`).join(''):'<div class="empty">还没有路线记录<br>从一场演示遛宠开始吧</div>'}</div><button class="secondary" style="margin-top:16px" data-a="walk-setup">开启遛宠</button></div>`,false)}
 function renderRouteDetail(){const w=data.walks.find(x=>x.id===routeId);if(!w){view='routes';return renderRoutes()}return shell(`<div class="wrap">${head('路线回放','删除','delete-route')}<div class="notice ${w.mode==='demo'?'warm':''}">${w.mode==='demo'?'这是模拟遛宠记录，不代表真实行程。':'定位记录只保存在本机；路线形状为示意，未叠加真实地图。'}</div>${mapBlock('history',visualPoints(w),w)}<div class="walk-info"><img class="avatar" src="${asset[w.petKind]||asset['其他']}" alt=""><span><strong>${e(w.petName)} 的遛宠时光</strong><small>${e(new Date(w.started).toLocaleString('zh-CN'))}</small></span></div><div class="stats"><div><strong>${elapsed(w)}</strong><small>时长</small></div><div><strong>${(meters(w)/1000).toFixed(2)}</strong><small>${w.mode==='demo'?'模拟公里':'记录公里'}</small></div><div><strong>${w.events.length}</strong><small>沿途打卡</small></div></div>${sec('沿途的小记忆','仅本机')}<div class="card" style="padding:0 14px">${w.events.length?w.events.map((x,i)=>`<div class="wide-action">${ico(x.type==='喝水'?'water':x.type==='交友'?'friends':x.type==='照片'?'camera':'mark')}<span><strong>${i+1}　${e(x.type)}</strong><small>${e(new Date(x.time).toLocaleTimeString('zh-CN'))}</small></span>${x.image?`<img class="avatar" src="${e(x.image)}" alt="沿途照片">`:''}</div>`).join(''):'<div class="empty">这次还没有沿途打卡</div>'}</div><p class="fine">重新进入本页可重播示意路线动画；不支持地图导航。</p></div>`,false)}
 function renderMap(){return shell(`<div class="wrap">${head('宠友地图')}<p class="sub">在同一个城市，发现喜欢宠物的朋友。</p>${mapBlock()}<div class="notice warm" style="margin-top:12px">地图道路和人物位置均为示意，不代表真实街道或实际附近的用户。正式版需要接入合规地图服务及经过授权的位置共享。</div>${sec('示例宠友','点击查看')}<div class="friends">${[['山山','狗'],['栗子','猫'],['团团','兔']].map((x,i)=>`<button class="friend" data-a="friend" data-v="${i}"><img src="${asset[x[1]]}" alt=""><strong>${x[0]} · 示例</strong><small>宠友资料演示</small></button>`).join('')}</div><button class="primary" style="margin-top:20px" data-a="walk-setup">开启遛宠</button></div>`,false)}
 function render(){let body;switch(view){case'home':body=renderHome();break;case'community':body=renderCommunity();break;case'care':body=renderCare();break;case'profile':body=renderProfile().replace('<div class="pet-hero">',petSelector()+'<div class="pet-hero">');break;case'pet-home':body=renderPetHome().replace('<div class="pet-stats">',petIdCard()+'<div class="pet-stats">');break;case'login':body=renderLogin();break;case'pet-form':body=renderPetForm();break;case'compose':body=renderCompose();break;case'detail':body=renderDetail();break;case'nest':body=renderNest();break;case'adoption':body=renderAdoption();break;case'adopt-detail':body=renderAdoptionDetail();break;case'health-form':body=renderHealthForm();break;case'health-history':body=renderHealthHistory();break;case'tips':body=renderTips();break;case'ai-chat':body=renderAiChat();break;case'portrait':body=renderPortrait();break;case'breed':body=renderBreed();break;case'shop':body=renderShop();break;case'shop-detail':body=renderShopDetail();break;case'merchant':body=renderMerchant();break;case'messages':body=renderMessages();break;case'friend':body=renderFriend();break;case'settings':body=renderSettings();break;case'walk-setup':body=renderWalkSetup().replace('<div class="pet-card card">',petSelector()+'<div class="pet-card card">');break;case'walk':body=renderWalk();break;case'routes':body=renderRoutes();break;case'route-detail':body=renderRouteDetail();break;case'map':body=renderMap();break;default:view='home';body=renderHome()}const oldScreen=app.querySelector('.screen'),oldScroll=oldScreen?.scrollTop||0,changed=renderedView!==view;app.innerHTML=body;const next=app.querySelector('.screen');if(next){if(changed)next.classList.add('screen-enter');else next.scrollTop=oldScroll}renderedView=view}
 const navState=()=>({paizhua:true,view,tab,stack:[...stack],detailId,adoptionId,routeId,friendIndex:window.friendIndex||0,shopItemId});
 function replaceNav(){history.replaceState(navState(),'')}
 function go(v){stack.push(view);view=v;render();history.pushState(navState(),'')}
 function switchTab(v){stack=[];tab=v;view=v;topic='';imageData='';render();history.pushState(navState(),'')}
 function navigateBack(){if(!stack.length&&view!==tab&&view!=='walk'){view=tab||'home';render();replaceNav();return}if(history.state?.paizhua)history.back();else{view=stack.pop()||tab||'home';render()}}
 window.addEventListener('popstate',event=>{if(ignoreNextPop){ignoreNextPop=false;return}if(view==='walk'&&walk){if(!confirm('结束并保存这次遛宠记录？')){ignoreNextPop=true;history.forward();return}finishWalk();return}const state=event.state;if(state?.paizhuaRoot){view='home';tab='home';stack=[];render();history.pushState(navState(),'');toast('已经回到首页');return}if(!stack.length&&view!==tab){view=tab||'home';render();replaceNav();return}if(state?.paizhua){view=state.view;tab=state.tab;stack=[...(state.stack||[])];detailId=state.detailId||'';adoptionId=state.adoptionId||'';routeId=state.routeId||'';shopItemId=state.shopItemId||'s1';window.friendIndex=state.friendIndex||0;render()}});
 let touchStart=null;app.addEventListener('touchstart',ev=>{if(ev.touches.length!==1||ev.target.closest('input,textarea,select,.chip-row,.friends'))return;const t=ev.touches[0],rect=app.getBoundingClientRect(),x=t.clientX-rect.left;if(x>=24&&x<=65)touchStart={x:t.clientX,y:t.clientY,side:'left'};else if(x>=rect.width-65&&x<=rect.width-24)touchStart={x:t.clientX,y:t.clientY,side:'right'};else touchStart=null},{passive:true});app.addEventListener('touchend',ev=>{if(!touchStart)return;const t=ev.changedTouches[0],dx=t.clientX-touchStart.x,dy=t.clientY-touchStart.y,side=touchStart.side;touchStart=null;if(((side==='left'&&dx>95)||(side==='right'&&dx< -95))&&Math.abs(dy)<45&&view!=='home'&&stack.length)navigateBack()},{passive:true});
 function openPetForm(isNew=false){petFormNew=isNew;petDraft=isNew?{}:{...(data.pets.length?pet():{})};selectedPet=['狗','猫'].includes(petDraft.kind)?petDraft.kind:'其他';if(!petDraft.kind)selectedPet='狗';sterilized=petDraft.sterilized||'未填写';go('pet-form')}
 function readPetDraft(){petDraft.name=$('#pet-name')?.value||'';petDraft.age=$('#pet-age')?.value||'';petDraft.breed=$('#pet-type')?.value||''}
 function stopWatch(){if(watchId!==null&&navigator.geolocation){navigator.geolocation.clearWatch(watchId);watchId=null}}
 function finishWalk(){if(!walk)return;walk.ended=Date.now();data.walks.push(walk);if(!save()){data.walks.pop();walk.ended=null;toast('未保存，请先释放本机空间');return}stopWatch();walk=null;stack=[];view='routes';render();replaceNav();toast('路线已保存到本机')}
 function addPosition(pos){if(!walk||walk.mode!=='real')return;const p={lat:pos.coords.latitude,lng:pos.coords.longitude,accuracy:pos.coords.accuracy,time:pos.timestamp||Date.now()};if(!Number.isFinite(p.lat)||!Number.isFinite(p.lng))return;let prev=walk.points[walk.points.length-1];if(!prev||distance(prev,p)>=5){if(!prev||distance(prev,p)<1000)walk.points.push(p)}if(walk.points.length>1000)walk.points.shift()}
 function startReal(){if(!window.isSecureContext||!navigator.geolocation){toast('当前页面不支持定位，请使用演示模式');return}toast('请在浏览器中选择是否允许定位');navigator.geolocation.getCurrentPosition(pos=>{if(view!=='walk-setup')return;walk={id:'w'+Date.now(),mode:'real',started:Date.now(),petId:pet().id,petName:pet().name,petKind:pet().kind,points:[],events:[]};addPosition(pos);go('walk');watchId=navigator.geolocation.watchPosition(addPosition,()=>toast('定位暂时不可用，请检查权限'),{enableHighAccuracy:true,maximumAge:3000,timeout:15000})},err=>toast(err.code===1?'未授权定位，可使用演示模式':'定位暂时不可用，可使用演示模式'),{enableHighAccuracy:true,timeout:15000,maximumAge:3000})}
 function addDays(date,n){let [y,m,d]=date.split('-').map(Number),z=new Date(y,m-1,d);z.setDate(z.getDate()+n);return `${z.getFullYear()}-${String(z.getMonth()+1).padStart(2,'0')}-${String(z.getDate()).padStart(2,'0')}`}
 function saveHealth(){const typ=$('#health-type')?.value,date=$('#health-date')?.value,cycle=Number($('#health-cycle')?.value||0),note=$('#health-note')?.value.trim()||'';if(!date){toast('请选择日期');return}let item={id:'h'+Date.now(),petId:pet().id,type:typ,date,cycle,note,done:false};data.health.push(item);if(!save()){data.health.pop();return}window.pendingType='';go('health-history');toast('已保存到本机')}
 app.addEventListener('click',ev=>{const el=ev.target.closest('[data-a]');if(!el)return;const a=el.dataset.a,v=el.dataset.v||'',id=el.dataset.id||'';
  if(a==='tab'){switchTab(v);return}
  if(a==='back'){navigateBack();return}
  if(a==='daily-toggle'){const done=data.daily?.date===today()&&data.daily?.petId===pet().id;data.daily=done?null:{date:today(),petId:pet().id};save();render();toast(done?'已取消今日记录':'已记录今天的陪伴');return}
  if(a==='login'){go('login');return}
  if(a==='login-next'){if(!$('#agree')?.checked){toast('请先勾选体验说明');return}if($('#code')?.value!=='123456'){toast('请输入体验验证码 123456');return}data.registered=true;save();openPetForm();return}
  if(a==='skip-login'){data.registered=true;save();switchTab('home');return}
  if(a==='pet-form'){openPetForm();return}
  if(a==='add-pet'){openPetForm(true);return}
  if(a==='choose-active-pet'){if(id==='demo')return;const p=data.pets.find(x=>x.id===id);if(p){data.currentPetId=id;data.pet=p;save();render()}return}
  if(a==='select-pet'){readPetDraft();selectedPet=v;render();return}
  if(a==='sterilized'){readPetDraft();sterilized=v;render();return}
  if(a==='save-pet'){readPetDraft();if(!petDraft.name.trim()){toast('请填写宠物名称');return}const petId=petFormNew||!petDraft.id?'pet'+Date.now():petDraft.id;data.pet={id:petId,name:petDraft.name.trim(),kind:selectedPet,age:petDraft.age.trim(),breed:petDraft.breed.trim(),sterilized,photo:petDraft.photo||''};data.pets=[...data.pets.filter(x=>x.id!==petId),data.pet];data.currentPetId=petId;data.registered=true;if(save()){const previous=stack.at(-1);if(previous==='walk-setup'||previous==='care'){view=stack.pop();render();replaceNav()}else switchTab('profile');toast('宠物档案已保存到本机')}return}
  if(a==='filter'){filter=v;render();return}
  if(a==='post-detail'){detailId=id;go('detail');return}
  if(a==='compose'||a==='topic'){topic=a==='topic'?'晒晒我家午睡选手':'';imageData='';voice='owner';go('compose');return}
  if(a==='voice'){voice=v;app.querySelectorAll('[data-a="voice"]').forEach(b=>{let on=b.dataset.v===voice;b.classList.toggle('active',on);b.setAttribute('aria-pressed',String(on))});return}
  if(a==='submit-post'){const text=$('#post-text')?.value.trim();if(!text){toast('写一句想分享的话吧');return}const p=pet(),post={id:'p'+Date.now(),animal:p.kind,author:voice==='pet'?p.name:'我',mine:true,petId:p.id,pet:p.name,title:text.slice(0,24),text:(topic?'# '+topic+'\n':'')+text,image:imageData||petPhoto(p),likes:0};data.posts.unshift(post);if(!save()){data.posts.shift();return}filter='推荐';switchTab('community');toast('动态已保存到本机相册');return}
  if(a==='like'){data.likes=data.likes.includes(detailId)?data.likes.filter(x=>x!==detailId):[...data.likes,detailId];save();render();return}
  if(a==='save-post'){data.saved=data.saved.includes(detailId)?data.saved.filter(x=>x!==detailId):[...data.saved,detailId];save();render();toast(data.saved.includes(detailId)?'已收藏到本机':'已取消收藏');return}
  if(a==='follow'){data.follows=data.follows.includes(v)?data.follows.filter(x=>x!==v):[...data.follows,v];save();render();return}
  if(a==='comment'){const msg=$('#comment')?.value.trim();if(!msg){toast('先写一句友好的话吧');return}data.comments[detailId]=[...(data.comments[detailId]||[]),msg];save();render();toast('回应仅保存到本机');return}
  if(a==='report'){toast('举报入口演示，未提交真实举报');return}
  if(a==='friend'){window.friendIndex=Number(v);go('friend');return}
  if(a==='hello'){toast('示例宠友，暂时不能发送真实消息');return}
  if(a==='invite'){const target=$('#invite-result');if(target)target.innerHTML='<div class="notice warm" style="margin-top:12px">邀请示例码：PZ-2026。此码不可用于真实共享，需接入账号与服务器后实现。</div>';return}
  if(a==='adopt-detail'){adoptionId=id;go('adopt-detail');return}
  if(a==='adopt-apply'){const msg=$('#adopt-note')?.value.trim();if(!msg){toast('先写一句话吧');return}data.adoptRequests.push({id:adoptionId,text:msg});save();toast('仅保存了本机意向示例，未发送');return}
  if(a==='health-form'){window.pendingType=v||'疫苗';go('health-form');return}
  if(a==='month'){calendarOffset+=Number(v);calendarFilter='';render();return}
  if(a==='calendar-day'){calendarFilter=calendarFilter===v?'':v;render();return}
  if(a==='clear-calendar'){calendarFilter='';render();return}
  if(a==='save-health'){saveHealth();return}
  if(a==='done-health'){let h=data.health.find(x=>x.id===id);if(!h)return;h.done=true;if(h.cycle){let copy={...h,id:'h'+Date.now(),date:addDays(h.date,h.cycle),done:false};data.health.push(copy)}save();render();toast(h.cycle?'已归档并生成下一次日期':'已完成并归档');return}
  if(a==='tip-detail'){toast('可咨询兽医获得适合你家宠物的建议');return}
  if(a==='chat-send'){const msg=$('#chat-input')?.value.trim();if(!msg){toast('先输入想咨询的问题');return}data.chat.push({role:'me',text:msg},{role:'demo',text:'这只是演示界面，未接入 AI 或兽医，无法分析病情。若宠物精神、呼吸或进食等出现明显异常，请尽快联系正规兽医。'});save();render();return}
  if(a==='art-type'){artType=v;render();return}
  if(a==='portrait-demo'){toast('正式版需要接入模型；当前仅展示示例画像');return}
  if(a==='breed-demo'){let x=$('#breed-result');if(x)x.innerHTML='<div class="ai-demo" style="margin-top:14px">示例结果：狗狗 / 金毛寻回犬。此结果为固定示例，并非对你上传图片的识别。</div>';return}
  if(a==='shop-filter'){shopFilter=v;render();return}
  if(a==='shop-detail'){shopItemId=id;go('shop-detail');return}
  if(a==='shop-back'){navigateBack();return}
  if(a==='merchant'){go('merchant');return}
  if(a==='merchant-save'){const name=$('#merchant-name')?.value.trim();if(!name){toast('请填写一个商家名称示例');return}data.merchantDemo={name,type:$('#merchant-type')?.value||'',savedAt:Date.now()};if(save())toast('示例已保存在本机，未提交入驻');return}
  if(a==='privacy-info'){toast('真实定位需主动授权；本原型不会上传位置');return}
  if(a==='clear-data'){if(confirm('确定清除当前浏览器中的全部体验数据？此操作无法撤销。')){stopWatch();walk=null;localStorage.removeItem(KEY);data=empty();switchTab('home');toast('已清除本机体验数据')}return}
  if(a==='walk-demo'){walk={id:'w'+Date.now(),mode:'demo',started:Date.now(),petId:pet().id,petName:pet().name,petKind:pet().kind,points:[],events:[]};go('walk');return}
  if(a==='walk-real'){startReal();return}
  if(a==='walk-event'){if(!walk)return;walk.events.push({type:v,time:Date.now(),point:walk.points.at(-1)||null});render();toast('已记录：'+v);return}
  if(a==='finish-walk'){finishWalk();return}
  if(a==='route-detail'){routeId=id;go('route-detail');return}
  if(a==='delete-route'){if(confirm('删除这条本机路线记录？')){data.walks=data.walks.filter(x=>x.id!==routeId);save();view='routes';render();replaceNav();toast('路线已删除')}return}
  if(['map','walk-setup','routes','pet-home','nest','adoption','health-history','tips','ai-chat','portrait','breed','shop','messages','settings'].includes(a)){if(a==='breed')imageData='';go(a);return}
 });
 app.addEventListener('keydown',ev=>{let el=ev.target.closest('.post');if(el&&(ev.key==='Enter'||ev.key===' ')){ev.preventDefault();el.click()}});
 app.addEventListener('change',ev=>{if(!['upload','breed-upload','walk-photo','pet-upload'].includes(ev.target.id))return;let file=ev.target.files?.[0];if(!file)return;if(!file.type.startsWith('image/')){toast('请选择图片文件');return}if(file.size>2*1024*1024){toast('请选择小于 2 MB 的图片');ev.target.value='';return}const targetId=ev.target.id;if(targetId==='pet-upload')readPetDraft();let reader=new FileReader();reader.onload=()=>{let img=String(reader.result);if(targetId==='walk-photo'){if(!walk)return;walk.events.push({type:'照片',time:Date.now(),image:img,point:walk.points.at(-1)||null});render();toast('沿途照片已添加，结束后保存到本机')}else if(targetId==='pet-upload'){petDraft.photo=img;let box=app.querySelector('label[for="pet-upload"]');if(box)box.innerHTML=`<img src="${img}" alt="已选宠物头像">`}else{imageData=img;let box=app.querySelector('.upload');if(box)box.innerHTML=`<img src="${img}" alt="已选照片">`}};reader.onerror=()=>toast('图片读取失败');reader.readAsDataURL(file)});
 setInterval(()=>{if(view!=='walk'||!walk)return;let a=$('#walk-time'),b=$('#walk-distance'),c=$('#walk-events');if(a)a.textContent=elapsed(walk);if(b)b.textContent=(meters(walk)/1000).toFixed(2);if(c)c.textContent=walk.events.length;let svg=app.querySelector('.map-svg'),pts=visualPoints(walk);if(svg&&pts.length>1){let line=svg.querySelector('polyline');if(!line){line=document.createElementNS('http://www.w3.org/2000/svg','polyline');line.setAttribute('stroke','#4b9b6c');line.setAttribute('stroke-width','4');line.setAttribute('fill','none');line.setAttribute('stroke-linecap','round');line.setAttribute('stroke-linejoin','round');svg.appendChild(line)}line.setAttribute('points',pts.map(p=>`${p.x},${p.y}`).join(' '))}},1000);
 window.addEventListener('beforeunload',()=>stopWatch());
 history.replaceState({paizhuaRoot:true},'');history.pushState(navState(),'');
 render();
})();
